    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data
        nodes_list = data['nodes']
        edges_list = data['edges']

        def find_maximal_cocktails(nodes, edges):
            # Build the adjacency list for the original graph
            graph = {node: set() for node in nodes}
            for u, v in edges:
                graph[u].add(v)
                graph[v].add(u)

            # Bron-Kerbosch algorithm to find maximal independent sets (maximal cliques in the complement graph)
            # Here, we treat the problem as finding maximal cliques in the complement graph
            # So, the adjacency for the complement graph is nodes not connected in the original graph
            complement_graph = {node: set() for node in nodes}
            for u in nodes:
                for v in nodes:
                    if u != v and v not in graph[u]:
                        complement_graph[u].add(v)

            # Now, find all maximal cliques in the complement graph
            # Implementing Bron-Kerbosch algorithm with pivoting
            maximal_cliques = []

            def bron_kerbosch(R, P, X):
                if not P and not X:
                    maximal_cliques.append(list(R))
                    return
                # Choose pivot from P union X for optimization
                pivot = next(iter(P.union(X)), None)
                for v in P.difference(complement_graph.get(pivot, set())):
                    bron_kerbosch(R.union({v}), P.intersection(complement_graph[v]), X.intersection(complement_graph[v]))
                    P = P.difference({v})
                    X = X.union({v})

            bron_kerbosch(set(), set(nodes), set())
            return maximal_cliques

        if message.difficulty == 'easy':
            maximal_cocktails = find_maximal_cocktails(nodes_list, edges_list)
            num_maximal_cocktails = len(maximal_cocktails)
        elif message.difficulty == 'normal':
            maximal_cocktails = find_maximal_cocktails(nodes_list, edges_list)
            maximal_cocktails_sorted = [sorted(list(cocktail)) for cocktail in maximal_cocktails]
            maximal_cocktails = maximal_cocktails_sorted

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=num_maximal_cocktails if message.difficulty == 'easy' else maximal_cocktails, type='custom')]
