                adjacency[v].add(u)

            maximal_sets = []
            current_set = []
            nodes_remaining = set(nodes)

            def backtrack(start, current_set, nodes_remaining):
                is_maximal = True
                for node in nodes_remaining:
                    if all(node not in adjacency[u] for u in current_set):
                        is_maximal = False
                        new_set = current_set + [node]
                        new_remaining = nodes_remaining - {node} - adjacency[node]
                        backtrack(start + 1, new_set, new_remaining)
                if is_maximal and current_set:
                    maximal_sets.append(current_set.copy())

            backtrack(0, current_set, nodes_remaining)
            return maximal_sets

        if message.difficulty == 'easy':
            maximal_sets = find_maximal_independent_sets()
            num_maximal_cocktails = len(maximal_sets)
        elif message.difficulty == 'normal':
            maximal_sets = find_maximal_independent_sets()
            maximal_cocktails = maximal_sets

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=num_maximal_cocktails if message.difficulty == 'easy' else maximal_cocktails, type='custom')]
        )

