class CountMaximalCocktailsCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.SMT

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data
        nodes_list = data['nodes']
        edges_list = data['edges']

        # Build adjacency list for quick lookup
        adjacency = {node: set() for node in nodes_list}
        for u, v in edges_list:
            adjacency[u].add(v)
            adjacency[v].add(u)

        def is_independent(current_set, node):
            for existing_node in current_set:
                if existing_node in adjacency[node]:
                    return False
            return True

        maximal_cocktails = []

        def backtrack(start, current_set):
            if start == len(nodes_list):
                # Check if current_set is maximal
                maximal = True
                remaining_nodes = [node for node in nodes_list if node not in current_set]
                for node in remaining_nodes:
                    if is_independent(current_set, node):
                        maximal = False
                        break
                if maximal:
                    maximal_cocktails.append(list(current_set))
                return

            node = nodes_list[start]
            # Option 1: Include the node if it's independent
            if is_independent(current_set, node):
                current_set.append(node)
                backtrack(start + 1, current_set)
                current_set.pop()
            # Option 2: Do not include the node
            backtrack(start + 1, current_set)

        backtrack(0, [])

        # For normal difficulty, return the list; for easy, return the count
        if message.difficulty == 'easy':
            num_maximal_cocktails = len(maximal_cocktails)
        elif message.difficulty == 'normal':
            maximal_cocktails = maximal_cocktails

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=num_maximal_cocktails if message.difficulty == 'easy' else maximal_cocktails, type='custom')]
        )
